package com.ethk3.novaonepro;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import com.ethk3.novaonepro.strategyv2.JsonR27;
import java.nio.file.*;
import java.sql.*;
import java.util.*;

/** Actual R929 strict metadata, Domain owner, and registry mutation on native SQLite. */
public final class R929MetadataR31Host {
    static int assertions;static final List<Object> facts=new ArrayList<>();
    static void need(boolean ok,String reason){assertions++;if(!ok)throw new AssertionError(reason);}
    static long n(SQLiteDatabase db,String sql){try(Cursor q=db.rawQuery(sql,null)){need(q.moveToFirst(),sql);return q.getLong(0);}}
    static String sql(SQLiteDatabase db,String table){try(Cursor q=db.rawQuery("SELECT sql FROM sqlite_master WHERE name=?",new String[]{table})){need(q.moveToFirst(),"table source "+table);return q.getString(0);}}
    static SQLiteDatabase open()throws Exception{return new SQLiteDatabase(DriverManager.getConnection("jdbc:sqlite::memory:"));}
    static void tx(SQLiteDatabase db,Runnable body,boolean commit){db.beginTransaction();try{body.run();if(commit)db.setTransactionSuccessful();}finally{db.endTransaction();}}
    static void owner(SQLiteDatabase db){tx(db,()->SchemaDomainCoordinatorR926.migrateR31PlatformPrerequisites(db),true);}
    static Map<String,Object> missing(SQLiteDatabase db,String reason){long version=n(db,"PRAGMA schema_version"),objects=n(db,"SELECT count(*) FROM sqlite_master");Map<String,Object> report=ResearchPlatformStoreR929.schemaReadinessReportR31(db);need(Boolean.FALSE.equals(report.get("ready")),"failed schema accepted:"+report);need(report.get("issues").toString().contains(reason),"wrong metadata reason:"+reason+"/"+report);try{ResearchPlatformStoreR929.requireSchemaReadOnlyR31(db);throw new AssertionError("bad schema required successfully");}catch(ResearchPlatformStoreR929.SchemaNotReadyR31 actual){need("DEPENDENCY".equals(actual.failureCategory()),"actual typed pending");need(actual.readiness.get("issues").toString().contains(reason),"actual throwable carries every measured schema failure");need(actual.toString().contains(String.valueOf(actual.readiness.get("reason"))),"actual throwable string preserves its exact primary failure");}need(version==n(db,"PRAGMA schema_version")&&objects==n(db,"SELECT count(*) FROM sqlite_master"),"diagnostic/readiness changed schema");return report;}
    static void fullContract()throws Exception{try(SQLiteDatabase db=open()){
        Map<String,Object> absent=missing(db,"MISSING_TABLE:research_trial_registry_r929");need(((List<?>)absent.get("issues")).size()==13,"all actual nine tables/four indexes reported");need(ResearchPlatformStoreR929.schemaObjectsR31().length==13,"exact startup object contract");
        tx(db,()->{SchemaDomainCoordinatorR926.migrateR31PlatformPrerequisites(db);need(ResearchPlatformStoreR929.schemaReadyReadOnlyR31(db),"uncommitted actual migration ready locally");},false);missing(db,"MISSING_TABLE:research_trial_registry_r929");need(n(db,"SELECT count(*) FROM sqlite_master WHERE name='research_model_bundle_r929'")==0,"rollback left half platform schema");
        owner(db);need(ResearchPlatformStoreR929.schemaReadyReadOnlyR31(db),"explicit original owner establishes strict contract");need(Boolean.TRUE.equals(ResearchPlatformStoreR929.schemaReadinessReportR31(db).get("ready")),"diagnostic verifies actual schema beyond memo");need(SchemaDomainCoordinatorR926.matches(db,SchemaDomainCoordinatorR926.r31PlatformPrerequisitesContract()),"actual platform Domain stamp");need(n(db,"SELECT count(*) FROM "+SchemaDomainCoordinatorR926.TABLE_DOMAIN+" WHERE domain='RESEARCH' AND state='READY'")==0,"minimal owner cannot certify whole Research");
        SQLiteDatabase.stage="BUSINESS_CAPTURE";int before=SQLiteDatabase.trace.size();tx(db,()->ResearchPlatformStoreR929.activateRuntimeBundle(db,ModelBundleRuntimeR932.current(),"202611041001",100),true);need(n(db,"SELECT count(*) FROM "+ResearchPlatformStoreR929.TABLE_BUNDLE+" WHERE state='ACTIVE'")==1,"actual seed registry captured");for(String call:SQLiteDatabase.trace.subList(before,SQLiteDatabase.trace.size())){String statement=call.split("\t",3)[2].trim();need(!statement.matches("(?is)^(CREATE|ALTER|DROP).*"),"business runtime DDL:"+call);}facts.add(Map.of("case","missing_rollback_actual_owner_and_business_capture","initialMetadata",absent,"businessDdl",0));
        SQLiteDatabase.stage="SCHEMA_NEGATIVE_CONTROLS";tx(db,()->{db.execSQL("DROP INDEX idx_r929_bundle_one_active");missing(db,"MISSING_INDEX:idx_r929_bundle_one_active");},false);need(ResearchPlatformStoreR929.schemaReadyReadOnlyR31(db),"rolled-back drift restored actual committed index");db.execSQL("DROP INDEX idx_r929_bundle_one_active");missing(db,"MISSING_INDEX:idx_r929_bundle_one_active");owner(db);need(ResearchPlatformStoreR929.schemaReadyReadOnlyR31(db),"declared owner restores missing actual index");
        String original=sql(db,ResearchPlatformStoreR929.TABLE_CERTIFICATE),noRevision=original.replace(",contract_revision TEXT NOT NULL DEFAULT ''","");need(!original.equals(noRevision),"exact missing-column fault");db.execSQL("DROP TABLE "+ResearchPlatformStoreR929.TABLE_CERTIFICATE);db.execSQL(noRevision);missing(db,"MISSING_COLUMN:research_certificate_r929:contract_revision");owner(db);need(ResearchPlatformStoreR929.schemaReadyReadOnlyR31(db),"existing additive column upgrade by actual owner");
        db.execSQL("DROP INDEX idx_r929_trial_family");db.execSQL("CREATE INDEX idx_r929_trial_family ON "+ResearchPlatformStoreR929.TABLE_TRIAL+"(status)");missing(db,"INDEX_DEFINITION_MISMATCH:idx_r929_trial_family");db.execSQL("DROP INDEX idx_r929_trial_family");owner(db);
        String nonUnique=original.replace("certificate_hash TEXT NOT NULL UNIQUE","certificate_hash TEXT NOT NULL");need(!nonUnique.equals(original),"exact global-unique fault");db.execSQL("DROP TABLE "+ResearchPlatformStoreR929.TABLE_CERTIFICATE);db.execSQL(nonUnique);db.execSQL("CREATE UNIQUE INDEX partial_certificate_hash ON "+ResearchPlatformStoreR929.TABLE_CERTIFICATE+"(certificate_hash) WHERE state='ACTIVE'");missing(db,"GLOBAL_UNIQUE_NOT_PROVEN:research_certificate_r929:certificate_hash");try{owner(db);throw new AssertionError("owner certified a partial unique as global");}catch(ResearchPlatformStoreR929.SchemaNotReadyR31 expected){assertions++;}need(!SchemaDomainCoordinatorR926.matches(db,SchemaDomainCoordinatorR926.r31PlatformPrerequisitesContract()),"bad uniqueness cannot get READY");
        String noPk=original.replace("candidate_key TEXT PRIMARY KEY NOT NULL","candidate_key TEXT NOT NULL");need(!noPk.equals(original),"exact PK fault");db.execSQL("DROP TABLE "+ResearchPlatformStoreR929.TABLE_CERTIFICATE);db.execSQL(noPk);missing(db,"PRIMARY_KEY_MISMATCH:research_certificate_r929");facts.add(Map.of("case","schema_drift_precise_reasons","covered",Arrays.asList("MISSING_INDEX","MISSING_COLUMN","INDEX_DEFINITION_MISMATCH","GLOBAL_UNIQUE_NOT_PROVEN","PRIMARY_KEY_MISMATCH"),"noRuntimeRepair",true));
    }}
    static void limitsAndUnknown()throws Exception{try(SQLiteDatabase db=open()){owner(db);for(int i=0;i<65;i++)db.execSQL("CREATE INDEX meta_limit_"+i+" ON "+ResearchPlatformStoreR929.TABLE_TRIAL+"(status)");Map<String,Object> report=missing(db,"METADATA_LIMIT:research_trial_registry_r929:indexes>64");need(((List<?>)report.get("issues")).size()<=64,"diagnostic reasons remain bounded");}SQLiteDatabase closed=open();closed.close();Map<String,Object> unknown=ResearchPlatformStoreR929.schemaReadinessReportR31(closed);need("UNKNOWN".equals(unknown.get("status")),"unavailable connection is unknown, not missing schema");facts.add(Map.of("case","bounded_metadata_and_unknown_source","unknown",unknown));}
    public static void main(String[] args)throws Exception{Class.forName("org.sqlite.JDBC");try{fullContract();limitsAndUnknown();System.out.println(JsonR27.write(Map.of("status","PASS","assertions",assertions,"facts",facts,"scope","ACTUAL_PRODUCTION_PLATFORM_METADATA_DOMAIN_CAPTURE_NATIVE_SQLITE_NOT_ART_DEVICE_OR_NATURAL")));}finally{if(args.length>0)Files.write(Paths.get(args[0]),SQLiteDatabase.trace);}}
}
